const body = $input.first().json.body;

const required = ['description', 'location', 'reporter_name'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}

const noiseTypes = ['music', 'construction', 'party', 'dog_barking', 'vehicle', 'shouting', 'machinery', 'other'];
const noiseType = noiseTypes.includes(body.noise_type) ? body.noise_type : 'other';

const severityRaw = parseInt(body.severity) || 5;
const severity = Math.min(10, Math.max(1, severityRaw));

return [{
  json: {
    valid: true,
    reporterName: body.reporter_name.trim(),
    reporterEmail: body.reporter_email || null,
    location: body.location.trim(),
    unit: body.unit || null,
    description: body.description.trim().slice(0, 1500),
    noiseType,
    severity,
    startTime: body.start_time || new Date().toISOString(),
    ongoingNow: body.ongoing_now === true || body.ongoing_now === 'true',
    previousComplaints: parseInt(body.previous_complaints) || 0,
    loggedAt: new Date().toISOString()
  }
}];

const all = $input.all().map(r => r.json);
const current = $('Validate Input').first().json;

// Complaints from same location in last 30 days
const cutoff = new Date();
cutoff.setDate(cutoff.getDate() - 30);

const sameLocation = all.filter(c => {
  const loc = (c.location || '').toLowerCase();
  const curLoc = current.location.toLowerCase();
  const logged = new Date(c.logged_at);
  return loc.includes(curLoc.slice(0, 15)) && logged >= cutoff;
});

const repeatCount = sameLocation.length;
const avgSeverity = sameLocation.length
  ? (sameLocation.reduce((s, c) => s + (parseFloat(c.severity) || 0), 0) / sameLocation.length).toFixed(1)
  : current.severity;

// Escalation logic
let escalationLevel = 'none';
if (current.severity >= 9 || (current.ongoingNow && current.severity >= 7)) {
  escalationLevel = 'immediate';
} else if (repeatCount >= 3 || current.severity >= 7) {
  escalationLevel = 'building_manager';
} else if (repeatCount >= 2 || current.severity >= 5) {
  escalationLevel = 'warning_letter';
}

return [{
  json: {
    current,
    repeatCount,
    avgSeverity,
    escalationLevel,
    sameLocationHistory: sameLocation.slice(-5)
  }
}];

values.content:
Process this noise complaint and generate the appropriate communications.

Complaint details:
- Reporter: {{ $json.current.reporterName }}
- Location: {{ $json.current.location }}{{ $json.current.unit ? ', Unit ' + $json.current.unit : '' }}
- Noise type: {{ $json.current.noiseType }}
- Severity (1-10): {{ $json.current.severity }}
- Ongoing right now: {{ $json.current.ongoingNow }}
- Description: {{ $json.current.description }}
- Logged at: {{ $json.current.loggedAt }}

Pattern analysis:
- Complaints from this location in last 30 days: {{ $json.repeatCount }}
- Average severity of those complaints: {{ $json.avgSeverity }}
- Escalation level determined: {{ $json.escalationLevel }}

Generate this JSON:
{
  "complaint_summary": "2-sentence neutral summary of the incident for internal records",
  "risk_assessment": "one of: low | medium | high | critical",
  "recommended_action": "what the property manager should do and why, in plain language, 2-3 sentences",
  "reporter_acknowledgement": {
    "subject": "email subject line",
    "body": "email body to the reporter — acknowledge receipt, explain what happens next, give a reference number (use logged_at timestamp as ref), under 120 words"
  },
  "formal_notice_needed": {{ $json.escalationLevel !== 'none' ? 'true' : 'false' }},
  "formal_notice": {
    "subject": "formal notice subject line or null",
    "body": "formal written notice to the offending unit/party if escalation_level is not none — factual, professional, references relevant building rules, under 200 words. null if no notice needed."
  },
  "next_steps": ["step 1", "step 2"]
}

