const raw = $input.first().json.text || $input.first().json.content?.[0]?.text || '';
let parsed;
try {
  parsed = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch(e) {
  return [{ json: { error: 'Parse failed', raw } }];
}

const pattern = $('Analyse Pattern').first().json;
parsed._escalationLevel = pattern.escalationLevel;
parsed._repeatCount = pattern.repeatCount;
parsed._reporterEmail = pattern.current.reporterEmail;
parsed._location = pattern.current.location;
parsed._loggedAt = pattern.current.loggedAt;

return [{ json: parsed }];
